//! The latest migration's `setting_definition()` (0251, regenerated by 0262, then 0269, then the PEOPLE-A void migration, then 0295, then 0296, then 0315, then 0316) function is generated from
//! the key roster, so the `BEFORE INSERT` trigger enforces the same kinds,
//! bounds, risk directions and governance as `check_change` (no reference
//! rows, no drift). On failure, paste the printed block into the migration.
#![allow(clippy::unwrap_used, clippy::panic)]

use console_settings_domain::{Governance, SettingKey, SettingKind};

const MIGRATION: &str =
    include_str!("../../../platform/db/migrations/20261027000000001_access_log_review.sql");
const BEGIN: &str = "-- BEGIN GENERATED by console-settings-domain tests/sql_definitions.rs";
const END: &str = "-- END GENERATED";

fn bigint(v: Option<i64>) -> String {
    v.map_or_else(|| "NULL::BIGINT".to_owned(), |v| format!("{v}::BIGINT"))
}

fn label<T: serde::Serialize>(v: T) -> String {
    serde_json::to_value(v)
        .unwrap()
        .as_str()
        .unwrap()
        .to_owned()
}

fn generated() -> String {
    let rows: Vec<String> = SettingKey::ALL
        .iter()
        // New read-only configuration has no storage path; retain legacy SQL rows for N-1.
        .filter(|key| {
            key.def().governance != Governance::ReadOnly
                || MIGRATION.contains(&format!("('{}',", key.as_str()))
        })
        .map(|key| {
            let def = key.def();
            let (kind, min, max, codes) = match def.kind {
                SettingKind::Int { min, max, .. } => ("int", min, max, "NULL::TEXT[]".to_owned()),
                SettingKind::Bool => ("bool", None, None, "NULL::TEXT[]".to_owned()),
                SettingKind::Code { allowed } => {
                    let list: Vec<String> = allowed.iter().map(|c| format!("'{c}'")).collect();
                    (
                        "code",
                        None,
                        None,
                        format!("ARRAY[{}]::TEXT[]", list.join(", ")),
                    )
                }
            };
            let default = def.default.and_then(|v| def.ordinal(v));
            format!(
                "        ('{}', '{kind}', {}, {}, {}, '{}', '{}', {codes})",
                key.as_str(),
                bigint(min),
                bigint(max),
                bigint(default),
                label(def.looser_when),
                label(def.governance),
            )
        })
        .collect();
    format!(
        "{BEGIN}\nCREATE OR REPLACE FUNCTION setting_definition(\n    p_key TEXT,\n    OUT kind TEXT,\n    OUT min_value BIGINT,\n    OUT max_value BIGINT,\n    OUT default_ordinal BIGINT,\n    OUT looser_when TEXT,\n    OUT governance TEXT,\n    OUT codes TEXT[]\n)\nLANGUAGE sql IMMUTABLE PARALLEL SAFE\nAS $$\n    SELECT d.kind, d.min_value, d.max_value, d.default_ordinal, d.looser_when, d.governance, d.codes\n    FROM (VALUES\n{}\n    ) AS d (key, kind, min_value, max_value, default_ordinal, looser_when, governance, codes)\n    WHERE d.key = p_key\n$$;\n{END}\n",
        rows.join(",\n")
    )
}

#[test]
fn migration_carries_the_generated_definitions() {
    let expected = generated();
    assert!(
        MIGRATION.contains(&expected),
        "the BW-00 migration is stale; replace its generated block with:\n{expected}"
    );
}
